def move_profile_checks(apps, schema_editor):
    # Profiles checked before per-profession checks keep their status; files go once decided.
    TesterProfile = apps.get_model("accounts", "TesterProfile")
    ProfessionCheck = apps.get_model("accounts", "ProfessionCheck")
    now = timezone.now()
    for profile in TesterProfile.objects.exclude(profession=""):
        common = {
            "tester_id": profile.user_id,
            "profession": profile.profession,
            "document_type": "profile_proof",
            "consent_at": profile.consent_at or now,
        }
        if profile.verification == "verified":
            decided = profile.verified_at or now
            ProfessionCheck.objects.create(
                **common, status="verified", decided_at=decided, expires_at=decided + timedelta(days=365)
            )
        elif profile.verification == "pending" and profile.proof:
            ProfessionCheck.objects.create(**common, document=profile.proof.name)
            continue
        if profile.proof:
            profile.proof.storage.delete(profile.proof.name)


